import { reactive } from 'vue'
import { STAFF, wardById, roleName, compById, initialScreens } from '../data/master.js'
import { fit, overlaps, layoutKey } from '../utils/helpers.js'

export const APP_KEY = Symbol('app')
export const PIN_SEC = 30 // 暫定値（LIMITS.pinTimeoutSec）
export const DEMO_PIN = '1234'
const ERR_AUTH = '職員カードまたはPINが正しくありません。もう一度職員カードをかざしてください。'
const ERR_TIMEOUT = '一定時間PINの入力がなかったため、最初からやり直してください。'

export function createAppStore () {
  const st = reactive({
    view: 'login', // login | main | term | select | edit
    stage: 'card', // card | pin
    staff: null, pin: '', err: '', remain: PIN_SEC, timerActive: false,
    ward: 'c5e', user: null, settingsOpen: false, now: new Date(),
    screens: initialScreens(),
    editId: null, draft: null, sel: null, hover: null, toast: ''
  })

  const ward = () => wardById(st.ward)
  const effective = () => {
    const r = st.user && st.user.id
    return st.screens.find(s => s.role === r && s.ward === st.ward) || st.screens.find(s => s.role === r && !s.ward) || st.screens[0]
  }
  const screenName = s => !s.role ? '病院全体（デフォルト）' : s.ward ? `${roleName(s.role)}・${wardById(s.ward).name}` : `${roleName(s.role)}（全病棟共通）`
  const screenScope = s => !s.role ? '病院全体' : s.ward ? '職種・病棟ごと' : '職種ごと（全病棟共通）'
  let toastTimer
  const flash = t => { clearTimeout(toastTimer); st.toast = t; toastTimer = setTimeout(() => { st.toast = '' }, 2200) }

  // ログイン
  const tapCard = staff => Object.assign(st, { stage: 'pin', staff, pin: '', err: '', remain: PIN_SEC, timerActive: true })
  const pressDigit = d => { if (st.pin.length < 6) { st.pin += d; st.remain = PIN_SEC; st.timerActive = true } }
  const backspace = () => { st.pin = st.pin.slice(0, -1); st.remain = PIN_SEC }
  const cancelPin = () => Object.assign(st, { stage: 'card', pin: '', staff: null, err: '' })
  const submitPin = () => {
    if (st.pin.length < 4) return
    if (st.pin === DEMO_PIN) Object.assign(st, { view: 'main', user: st.staff, stage: 'card', pin: '', err: '' })
    else Object.assign(st, { stage: 'card', pin: '', staff: null, err: ERR_AUTH })
  }
  const tick = () => {
    st.now = new Date()
    if (st.view !== 'login' || st.stage !== 'pin' || !st.timerActive) return
    if (st.remain <= 1) Object.assign(st, { stage: 'card', pin: '', staff: null, err: ERR_TIMEOUT })
    else st.remain--
  }
  const logout = () => Object.assign(st, { view: 'login', user: null, stage: 'card', pin: '', err: '', settingsOpen: false, draft: null })

  // 画面遷移
  const goMain = () => Object.assign(st, { view: 'main', settingsOpen: false })
  const goTerm = () => Object.assign(st, { view: 'term', settingsOpen: false })
  const goSelect = () => Object.assign(st, { view: 'select', settingsOpen: false, draft: null, sel: null })
  const setWard = id => { st.ward = id; flash(`設置病棟を「${wardById(id).name}」に更新しました`) }

  // 業務画面設定
  const editing = () => st.screens.find(s => s.id === st.editId)
  const isReadonly = () => { const s = editing(); return !s || !s.role }
  const isDirty = () => !!st.draft && layoutKey(st.draft) !== layoutKey(editing().items)
  const openEdit = id => { const s = st.screens.find(x => x.id === id); Object.assign(st, { view: 'edit', editId: id, draft: s.items.map(i => i.slice()), sel: null, hover: null }) }
  const addScreen = withWard => {
    const id = st.user.id + (withWard ? '-' + st.ward : '-all')
    if (st.screens.some(s => s.id === id)) return
    st.screens.push({ id, role: st.user.id, ward: withWard ? st.ward : null, items: effective().items.map(i => i.slice()) })
    openEdit(id)
    flash('業務画面を追加しました（現在の画面を複製）')
  }
  const selectComp = id => { st.sel = st.sel === id ? null : id; st.hover = null }
  const placeAt = (c, r) => {
    if (isReadonly()) return
    if (!st.sel) { // 未選択でタップ → そのセルのコンポーネントを選択
      const hit = st.draft.find(([t, x, y]) => { const m = compById(t); return c >= x && c < x + m.w && r >= y && r < y + m.h })
      if (hit) st.sel = hit[0]
      return
    }
    const f = fit(st.sel, c, r)
    st.draft = st.draft.filter(it => it[0] !== st.sel && !overlaps(it, f)).concat([[st.sel, f.c, f.r]])
    st.sel = null; st.hover = null
  }
  const removeItem = type => { st.draft = st.draft.filter(i => i[0] !== type) }
  const cancelEdit = () => Object.assign(st, { view: 'select', draft: null, sel: null })
  const save = () => {
    if (!isDirty() || isReadonly()) return
    editing().items = st.draft.map(i => i.slice())
    flash('レイアウトを保存しました')
  }

  // デザイン確認用の初期シーン
  function applyScene (scene) {
    const login = id => { const s = STAFF.find(x => x.id === id); Object.assign(st, { user: s, ward: s.ward, view: 'main' }) }
    switch (scene) {
      case 'login-pin': Object.assign(st, { stage: 'pin', staff: STAFF[0], pin: '12', remain: 24 }); break
      case 'login-error': st.err = ERR_AUTH; break
      case 'work-doctor': login('doctor'); break
      case 'work-pharm': login('pharm'); break
      case 'work-ce': login('ce'); break
      case 'settings': login('doctor'); st.settingsOpen = true; break
      case 'terminal': login('doctor'); st.view = 'term'; break
      case 'screen-select': login('doctor'); st.view = 'select'; break
      case 'layout-edit': login('doctor'); openEdit('doctor-c5e'); st.sel = 'labCardio'; break
      case 'layout-placing': login('doctor'); openEdit('doctor-c5e'); st.draft = st.draft.filter(i => i[0] !== 'dates').concat([['obsVital', 3, 0]]); st.sel = 'labHepRenal'; st.hover = [1, 1]; break
      case 'layout-default': login('doctor'); openEdit('h'); break
    }
  }

  return {
    st, ward, effective, screenName, screenScope, flash,
    tapCard, pressDigit, backspace, cancelPin, submitPin, tick, logout,
    goMain, goTerm, goSelect, setWard,
    editing, isReadonly, isDirty, openEdit, addScreen, selectComp, placeAt, removeItem, cancelEdit, save, applyScene
  }
}

