import { compById } from '../data/master.js'

export const COLS = 4
export const ROWS = 2

// レベル → クラス
export const bg = l => (l ? 'lvbg-' + l : '')
export const fg = l => (l ? 'lvfg-' + l : '')
export const vColor = l => ({ crit: 'error', warn: 'warning', ok: 'success', info: 'info' }[l] || undefined)
export const flagClass = f => (f === 'H' ? 'flag-h' : f === 'L' ? 'flag-l' : '')

const num = v => parseFloat(String(v).replace(/,/g, ''))
export const trend = (v, pv) => (!pv ? '' : num(v) > num(pv) ? '↑' : num(v) < num(pv) ? '↓' : '→')

const p2 = n => String(n).padStart(2, '0')
export const hm = (d = new Date()) => p2(d.getHours()) + ':' + p2(d.getMinutes())
export const md = (d = new Date()) => d.getMonth() + 1 + '/' + d.getDate()
export const ymdw = d => `${d.getFullYear()}/${p2(d.getMonth() + 1)}/${p2(d.getDate())}（${'日月火水木金土'[d.getDay()]}）`

// 配置アイテム [type, c, r] → グリッド座標
export function footprint (items) {
  const occ = new Set()
  const out = items.map(([type, c, r]) => {
    const m = compById(type)
    for (let i = 0; i < m.w; i++) for (let j = 0; j < m.h; j++) occ.add(c + i + ',' + (r + j))
    return { type, c, r, w: m.w, h: m.h, short: m.short, gc: `${c + 1} / span ${m.w}`, gr: `${r + 1} / span ${m.h}` }
  })
  const empty = []
  for (let r = 0; r < ROWS; r++) for (let c = 0; c < COLS; c++) if (!occ.has(c + ',' + r)) empty.push({ gc: String(c + 1), gr: String(r + 1) })
  return { items: out, empty }
}
// 定義サイズがはみ出さない位置に補正
export function fit (type, c, r) {
  const m = compById(type)
  return { c: Math.min(c, COLS - m.w), r: Math.min(r, ROWS - m.h), w: m.w, h: m.h }
}
export function overlaps ([t, a, b], x) {
  const m = compById(t)
  return !(a + m.w <= x.c || x.c + x.w <= a || b + m.h <= x.r || x.r + x.h <= b)
}
export const layoutKey = items => JSON.stringify(items.map(i => i.join(':')).sort())
